<script setup>import {useCartStore} from '../stores/cart';const cart=useCartStore()</script><template><section class="checkout-page"><div><span class="eyebrow">CART</span><h1>Shopping Cart</h1><p>Review your selected items before checking out.</p><div v-if="cart.items.length" class="cart-list"><article v-for="i in cart.items" :key="i.id" class="cart-item"><div class="cart-thumb"><div class="device-shape small"></div></div><div><h3>{{i.name}}</h3><small>SKU: {{i.sku}} · IN STOCK</small><div class="qty"><button @click="cart.setQty(i.id,i.qty-1)">−</button><b>{{i.qty}}</b><button @click="cart.setQty(i.id,i.qty+1)">+</button></div></div><strong>${{(i.price*i.qty).toFixed(2)}}</strong><button class="text-button" @click="cart.remove(i.id)">Remove</button></article></div></div><aside class="summary"><h3>Cart Summary</h3><div><span>Subtotal ({{cart.count}} items)</span><b>${{cart.subtotal.toFixed(2)}}</b></div><div><span>Discount</span><b>-${{cart.discount.toFixed(2)}}</b></div><div><span>Estimated Shipping</span><span>Calculated at checkout</span></div><div><span>Estimated Tax</span><span>Calculated at checkout</span></div><hr><div class="total"><span>Total</span><b>${{cart.total.toFixed(2)}}</b></div><RouterLink class="button button-blue full" to="/checkout/shipping">Proceed to Checkout</RouterLink></aside></section></template>
